EXEC sem.sp_Metric_Upsert @MetricId=N'fifo_garanti_tier', @Ad=N'fifo_garanti_tier', @Kaynak=NULL, @Formul=NULL, @Tuzak=N'aciklama: Açılış SP (sp_Fifo_AcilisCalistir_V2 ADIM 5.5) — tüm tier sonrası maliyetsiz/katmansız stok için FİYAT 0 OLAMAZ garantisi. · oncelik: 1) UrunBilgi.SonAlis>0 (gerçek son-alış = gerçek-ürün ayracı) → 2) SatisFiyat × kategori-marj oranı (AVG cost/satış per KatAna, ≥20 ürün) → 3) kategori ortalama mutlak maliyet → 4) impute-EDİLEMEZ → DEVRE DIŞI (non-inventory) · sabit_kaldirildi: 1-TL @GarantiSabitFiyat KALDIRILDI (19.06): non-inventory''yi (sınav süreli yayın/hediye çeki/kafe) %100 marj sayıp Ocak''ı +1.37M şişiriyordu (272 kalem). Artık impute-edilemez=devre-dışı. · sonalis_dersi: Salt kategori-imput gerçek ürünleri (SonAlis>0 ama kategori-dışı) yanlış devre-dışı yapıyordu → SonAlis tier eklendi → yanlış-dışlama=0. SonAlis=0 = non-inventory ayracı. · last_verified: 2026-06-19', @Birim=NULL, @Guven=0.85, @Kanit=N'pusula/sema/metrics.yaml', @Durum=N'teyit bekliyor', @TtlGun=180;
EXEC sem.sp_Metric_Upsert @MetricId=N'fifo_fiyat_0_olamaz', @Ad=N'fifo_fiyat_0_olamaz', @Kaynak=N'FifoKatman.BirimMaliyet<=0 KESİNLİKLE yasak (fifo-domain §6). 0 = sessiz %100-marj. GATE: SELECT COUNT(*) FROM FifoKatman WHERE BirimMaliyet<=0 → 0 dönmeli. + katmansız açılış stok (devre-dışı hariç) = 0.', @Formul=NULL, @Tuzak=NULL, @Birim=NULL, @Guven=0.85, @Kanit=N'pusula/sema/metrics.yaml', @Durum=N'teyit bekliyor', @TtlGun=180;
