EXEC sem.sp_Metric_Upsert @MetricId=N'marka_devir', @Ad=N'marka_devir', @Kaynak=NULL, @Formul=NULL, @Tuzak=N'aciklama: Marka/yayınevi (urn.urnMrkID → urnMrk.mrkID) bazında sermaye verimliliği = stok devir hızı + iade oranı. · devir: son 12 ay satış adet / anlık stok adet. Satış adet = -SUM(ehAdetN) ehTip IN(4,100). Stok = SUM(stokSonAltDepo_vw.stok) ehAltDepo=0, mekan 1/4477/4478/12. <1,5× = sermaye tuzağı (sipariş-kes sinyali), 1,5–3× izle, >3× sağlıklı. stok=0 → null (tükenmiş). · iade_orani: iade tutar / brüt satış tutar. iade = ehTip IN(3,5,101) ehTutarN; brüt = ehTip IN(4,100). >%10 kırmızı bayrak. · dislama: İç-operasyon + ev-markası: mrkID 0=Markasız, 269=BKM Kitap, 2101=Sınav Okulları, 5972=Sınav Kıyafet, 10911=BKM-Mağaza. + satış adet ≥50 gürültü eşiği. · perf: Satış agregatı + stok agregatı AYRI derived-table, mrkID''de JOIN (~17s). Satır-başı OUTER APPLY stok korelasyonu → timeout (sql-server-conventions filtreyi-aşağı-it dersi). · bulgu: 22.06: Faber-Castell devir 0,46× (636K stok, sermaye tuzağı) · Yapı Kredi 1,28× · Bilgi Sarmal 9,7× ama iade %12,4. PARAF/Fenomen/Timaş Çocuk sağlıklı. · last_verified: 2026-06-22', @Birim=NULL, @Guven=0.85, @Kanit=N'pusula/sema/metrics.yaml', @Durum=N'teyit bekliyor', @TtlGun=180;
EXEC sem.sp_Metric_Upsert @MetricId=N'kapanis_mudahale', @Ad=N'kapanis_mudahale', @Kaynak=NULL, @Formul=NULL, @Tuzak=N'aciklama: Kapanmış muhasebe ayına SONRADAN dokunma (ISA 240 post-closing). Kaynak: dbo.car + dbo.fat(eTip 6,7,8) + mhs.mhsFisBaslik. · mudahale: giriş(gTarih/cgTarih) VEYA değişim(kTarih/ckTarih) > Fin_AyKapanis.KapanisDT (belge ayının kapanış tarihi). GecGiris/SonradanDeg bayrak. · severity: 3=ikisi · 2=sonradan-değişim · 1=geç-giriş · 0=yok. RiskSkor = severity×100 + min(GunSonra,90) + round-number(25) + giren=onaylayan(20) + mükerrer(15). · forensic: round-number (ABS(tutar)%1000=0 & ≥1000) · mükerrer (kaynak+gider+ABS(tutar)+belge-tarih >1) · giren=onaylayan (kisi giren=onay; küçük ekipte YAPISAL, kişisel şüphe değil). · sadece_gider: frm/urn ''G-%'' (car/fat) · hspKod 6xx/7xx (mhs) — codes.gider_konvansiyonu · arac: bkm.sp_KapanisMudahaleKontrol_v2 (@Mod OZET/DETAY, @GiderKod drill). Panel /muhasebe + skill muhasebe-denetci. · bulgu: 22.06 canlı: 2025-Eki 11,79M ₺ kapanış-sonrası (Şule, açılmadı) · MHS manuel 100-164g geç (pinar.muhasebe1, Ara''25 31 fiş/132g) · 2026 görece temiz (CAR aylık <600K). Tem''25 Özge giren≠onaylayan = nadir gerçek-SoD. · confidence: 0.95 · last_verified: 2026-06-22', @Birim=NULL, @Guven=0.85, @Kanit=N'pusula/sema/metrics.yaml', @Durum=N'teyit bekliyor', @TtlGun=180;
EXEC sem.sp_Metric_Upsert @MetricId=N'kesin_mizan', @Ad=N'kesin_mizan', @Kaynak=NULL, @Formul=NULL, @Tuzak=N'aciklama: Genel muhasebe mizanı — ana(3-hane)→alt(100.10)→en alt(100.10.001) hiyerarşi. Dönem = fisSirketID (yıl−2020). · formula: Bakiye = Borç − Alacak (borç-pozitif). Borç=SUM(fisBA=1 → -fisTutar), Alacak=SUM(fisBA=0 → fisTutar). Kaynak mhsFis (mhsMizan_vw DEĞİL — kapanış içeriyor). · kapanis_haric: Kapanmış yıl: ''Kapanış'' bilanço fişi HARİÇ (codes mhsFisBaslik.fisAd_sistem) → gerçek bakiye. NOT EXISTS(fisAd=N''Kapanış''). Açık yıl etkisiz (Kapanış yok). VİRMAN''lar DAHİL (590 dönem kârı görünür). · nakit_pozisyon: 100+101+102+108 borç bakiyesi (103 Verilen Çek KONTRA → AYRI göster, nakit''e KATMA — katarsa -219M yanıltır, doğru +578M). · kdv_net: 391 hesaplanan (alacak bak) − 191 indirilecek (borç bak). Pozitif=ödenecek, negatif=devreden. · dogrulama: 23.06 kullanıcı 2025 Excel mizanı: 100/102/120/320/600 KURUŞU KURUŞUNA ✓, denge Borç=Alacak=28,93 mlr. 590 dönem kârı 5,87M fark = Excel 28.04 snapshot, 692/590 virman 30.04 revize (veri/zamanlama, formül değil). · arac: MizanQueries.GetSonucAsync · /mizan (Mizan.razor + MizanDugum recursive). TekDuzenHesap (79 ana hesap adı). · confidence: 1.0 · last_verified: 2026-06-23', @Birim=NULL, @Guven=0.85, @Kanit=N'pusula/sema/metrics.yaml', @Durum=N'teyit bekliyor', @TtlGun=180;
EXEC sem.sp_Metric_Upsert @MetricId=N'reorder_oneri_motoru', @Ad=N'reorder_oneri_motoru', @Kaynak=NULL, @Formul=NULL, @Tuzak=N'proc: bkm.OneriSiparisHesaplaSapmaDuzeltmeli (gece batch → entity bkm.OneriSiparis). Şube 1/4477/4478. · model: min-max (s,S): Minimum = günlük_hız × min_stok_gün(15); Maximum = × max_stok_gün(30); OneriSiparisAdet = (Stok ≤ Minimum ve Miktar180>0) ? Maximum−Stok : 0. GunStok = Stok×90/Miktar180. Açık PO bakiye (sipBakiye_vw) stoğa eklenir (çift-sipariş önler). Kategori3 (OneriSiparisKtg3Ondeger) min/max override. · gunluk_hiz: DuzeltilmisOrt = irsHrk satış (ehTip 1/4/100, -ehAdetN) / gün, ortTarih penceresi (kategori OrtSatisGun ya da 90g). · spike_sonumleme: ''Sapma-Düzeltmeli'': bir günün satışı ortalamanın 1.8 katını aşarsa o gün ortalamayla değiştirilir (toplu alım/etkinlik talebi şişirmesin). ⚠️ YALNIZ kategori 2,15,24,8,12,16 — keyfi/hardcoded. · kalibrasyonsuz_uyari: sabitler 1.8/15/30/90g/45g-yeni KALİBRE DEĞİL (opinion). Talep SANSÜRÜ düzeltilmiyor: stoksuz gün = kayıp satış kaydedilmez → satış gerçek talepten az → öneri EKSİK çıkar. Aynı-gün delete+insert → gün-içi öneri audit''i yok (ama gün-ler arası birikir). · backtest_bulgu_2026_07_30: ENS offline backtest (mağaza 1, bkm.OneriSiparis self-join): satış yoğunluğu (Miktar90) güven-proxy''si tahmin güvenilirliğini AYIRIYOR — SMAPE 2.0(ölü)→0.66(çok-yoğun), 6 tarihte replike, sezon-bağımsız. %74.7 ürün ÖLÜ stok (90g satış=0) → triyaj: insan dikkati yoğun-satanlara, ölüler bastırılır. Naive trailing-tahmin sapması SEZONLUK (yaza fazla/güze eksik, 6-tarih ortalamada eriyor). → forecast doğruluğu değil, GÜVEN kalibrasyonu + kayıp-satış düzeltmesi asıl kazanç. · confidence: 0.9 · evidence: 2026-07-30 — proc gövdesi (13KB) okundu + bkm.OneriSiparis self-join backtest (mağaza 1, 6 tarih D→D+30, SMAPE bucket). Arşiv: sorgular/2026-07-30-oneri-siparis-backtest.sql.', @Birim=NULL, @Guven=0.85, @Kanit=N'pusula/sema/metrics.yaml', @Durum=N'teyit bekliyor', @TtlGun=180;
EXEC sem.sp_Metric_Upsert @MetricId=N'satinalma_accountability', @Ad=N'satinalma_accountability', @Kaynak=NULL, @Formul=NULL, @Tuzak=N'zincir: Öneri (OneriSiparis.OneriSiparisAdet, s,S nötr taban) → Talep/Sipariş (OneriSiparisTalep.SiparisMiktar = ALICI kararı) → Mal Kabul (MalKabulSatirLog.Miktar = gerçek gelen) → Stok/Satış (outcome: devir/ölü-stok/stockout) · kose_tasi: ÖNERİ-SAPMASI = SiparisMiktar − OneriSiparisAdet (aynı Tarih/MekanId/StkId). Kontrol-edilebilir+ölçülebilir+adil. Alıcı öneriyi ezip fazla aldı & SKU ölü kaldı → alıcı sorumlu; öneriyi izledi & kötü → SİSTEM sorumlu (s,S nötr taban confound''u çözer). · fill_rate: gelen/sipariş = MalKabulSatirLog.Miktar / OneriSiparisTalep.SiparisMiktar. Kısa-fill = EksikIrsaliyeNo/IadeIrsaliyeNo → TEDARİKÇİ başarısızlığı (alıcı değil); kronik+alıcı o tedarikçide ısrar → alıcı (tedarikçi-seçimi). · atif: Alıcı = OneriSiparisTalep.OnaylayanKullanici (varchar-isim) + OneriSiparisKullaniciKategori (kategori-sahipliği). ⚠ MalKabul.OlusturanKullaniciId/KullaniciId = KABUL PERSONELİ, alıcı DEĞİL (haksız-atıf tuzağı). · perverse_incentive: Sapma-cezası → alıcı ''hep öneriyi izle''ye kaçar (sistem kör-noktalarında insan düzeltmesi ölür). KARŞI-METRİK: sapma→HAKLI (devir iyi) çıktıysa ÖDÜL; öneriyi izleyip stockout=sistem hatası (alıcıya yazma). · adil_atif: Confound elemesi ZORUNLU (talep şoku/sezon/kampanya-zorlaması/yayınevi fiyat = kontrol-dışı). Sinyal=sistematik pattern; tek SKU=gürültü. Overclaim yasak: iddia=kanıt+güven. Skill: .claude/skills/satinalma-danisman. · acik: Sipariş↔MalKabul köprüsü çok-hoplu (Talep.SipId→sip→irs/malkabul); doğrudan FK ve EvrakNo YOK (test edildi 0 örtüşme). fill_rate için bu köprü keşfedilmeli. · confidence: 0.7 · last_verified: 2026-07-30 · evidence: 2026-07-30 canlı sqlcli — OneriSiparisTalep/KullaniciKategori/MalKabulBaslik/SatirLog profil + EvrakNo köprü testi (0 örtüşme). Eksen tam-tasarımı bekliyor (öneri-sapması→ölü-stok).', @Birim=NULL, @Guven=0.85, @Kanit=N'pusula/sema/metrics.yaml', @Durum=N'teyit bekliyor', @TtlGun=180;
EXEC sem.sp_Metric_Upsert @MetricId=N'oneri_sapmasi', @Ad=N'oneri_sapmasi', @Kaynak=NULL, @Formul=NULL, @Tuzak=N'tanim: ÖNERİ-SAPMASI = bkm.OneriSiparisTalep.SiparisMiktar − bkm.OneriSiparis.OneriSiparisAdet, join (Tarih, MekanId, StkId). Öneri motoru bir adet önerir, insan değiştirir → sapma = kontrol edilebilir karar. · neden_adil: Ham talep hacmi ŞUBE BENİMSEMESİNE bağlı (İst.Yolu %70) → kişi kıyasında haksız. Sapma ORANI benimsemeden bağımsız; aynı kişinin kendi kararını öneriyle kıyaslar. · join_perf: OneriSiparis PK CLUSTERED (Tarih, MekanId, StkId) = tam join anahtarı → talep tarafından SEEK. CAST(t.Tarih AS date) KÜÇÜK tarafta yapılır (208M satırlık tabloda CAST seek''i bozar). Canlı: 111K talep × 208M öneri ≈ 2,2s. · eslesme_orani: Talep satırlarının ~%99''u öneri kaydıyla eşleşiyor (2026-08-18 canlı). Eşleşme <%90 olan kullanıcıda oranlar şüpheli — UI uyarı rengi gösterir. · kirpma: ⚠️ Satır oranı [-100%, +200%] KIRPILIR, sonra ortalanır. Sebep: düz ortalama tek uç satıra teslim (öneri=1 → talep=50 = +4900%); canlıda ist.kirtasiye %262,5 çıkmıştı, kırpma sonrası %49,3. Kırpılan satır sayısı UI''da parantezde ŞEFFAF gösterilir (sessiz kırpma yasak). Alt sınır -100% doğal (talep=0). · turev_gostergeler: AynenOran (öneriyi değiştirmeden kabul — %100 ise KARAR DEĞİL ONAY) · FazlaOran (öneriden fazla isteme = aşırı-alım yönü) · AzOran (öneriden az = stockout yönü) · OnayOran (kontrol katmanı) · GunlukTalep (aktif-güne normalize) · TekSeferlik (≤2 aktif gün → oranlar temsili değil). · canli_bulgu: 2026-08-18/19 (pencere 01.02.2025+): sirac.yigit + omerfaruk.kirmaci %100 AYNEN → öneri motorunu onaylıyorlar, kendi kararlarını koymuyorlar (sirac ayrıca %14 onay = talepleri reddedilmiş). ist.cocuk %56,2 FAZLA + %38,7 aynen → en çok müdahale eden. fsm.kultur %21 fazla / %20 az (dengeli, net sapma negatif). ozl.kultur %97,1 aynen (neredeyse hiç müdahale). · uygulama: dashboard/Data/SatinalmaQueries.Atif.cs → Alım Analizi ''Talep Sapması'' sekmesi (plan-34 B-146). Whitelist + hesap birleştirme + pencere Ayarlar''dan. · confidence: 0.95 · evidence: 2026-08-19 — canlı join 29 kullanıcı×ş', @Birim=NULL, @Guven=0.85, @Kanit=N'pusula/sema/metrics.yaml', @Durum=N'teyit bekliyor', @TtlGun=180;
GO

-- ─── Dogrulanmis (golden) sorgular ───────────────────────────────────

EXEC sem.sp_Query_Upsert @QueryId=N'aylik-magaza-net-ciro', @Soru=N'Mağaza bazında aylık net ciro (KDV hariç)', @DogrulanmisSql=N'SELECT FORMAT(H.ehTrhS,''yyyy-MM'') ay, M.mekanAd,
       SUM(CASE WHEN H.ehTip IN (1,4,100) THEN H.ehTutarN ELSE 0 END)
     - SUM(CASE WHEN H.ehTip IN (3,5,101) THEN H.ehTutarN ELSE 0 END) AS net_ciro
FROM dbo.irsHrk H WITH(NOLOCK)
JOIN dbo.mekan_vw M ON M.mekanID=H.ehMekan
WHERE H.ehTrhS >= CONVERT(date,''01.01.2026'',104)
  AND H.ehAltDepo=0 AND H.ehTip IN (1,3,4,5,100,101)
GROUP BY FORMAT(H.ehTrhS,''yyyy-MM''), M.mekanAd', @IlgiliMetrik=N'net_ciro', @IlgiliKopru=NULL, @SonucNotu=NULL, @Guven=0.95, @Kanit=N'pusula/sema/queries.yaml; calistirilarak dogrulandi', @TtlGun=180;
EXEC sem.sp_Query_Upsert @QueryId=N'encore-pos-gunluk-ciro', @Soru=N'EncoreMerkez POS günlük ciro (iade düşülmüş, indirim Direct)', @DogrulanmisSql=N'SELECT CONVERT(date, s.SaleDate) gun,
       SUM(CASE WHEN s.DocumentsTypeId=3 THEN -s.GrossTotal ELSE s.GrossTotal END) brut,
       SUM(CASE WHEN s.DocumentsTypeId=3 THEN -s.DiscountTotalDirect ELSE s.DiscountTotalDirect END) indirim
FROM EncoreMerkez.dbo.Sales s WITH(NOLOCK)
WHERE s.DocumentsTypeId IN (1,2,3,6,7,8)
  AND s.SaleDate >= CONVERT(date,''01.06.2026'',104)
GROUP BY CONVERT(date, s.SaleDate)', @IlgiliMetrik=NULL, @IlgiliKopru=NULL, @SonucNotu=NULL, @Guven=0.95, @Kanit=N'pusula/sema/queries.yaml; calistirilarak dogrulandi', @TtlGun=180;
EXEC sem.sp_Query_Upsert @QueryId=N'pos-urun-kategori-koprusu', @Soru=N'POS satışını DerinSIS kategorisine bağla (Products.Code=stkID)', @DogrulanmisSql=N'SELECT ub.KatAna, SUM(sp.Quantity) adet, SUM(sp.RowTotal) ciro
FROM EncoreMerkez.dbo.SalesProducts sp WITH(NOLOCK)
JOIN EncoreMerkez.dbo.Sales s WITH(NOLOCK) ON s.Id=sp.SalesId
JOIN EncoreMerkez.dbo.Products p WITH(NOLOCK) ON p.Id=sp.ProductsId
JOIN DerinSISBkm.bkm.Urunbilgi ub ON ub.stkID = CONVERT(int, p.Code)
WHERE sp.IsValid=1 AND s.DocumentsTypeId IN (1,2,3,6,7,8)
  AND ISNUMERIC(p.Code)=1
  AND s.SaleDate >= CONVERT(date,''01.06.2026'',104)
GROUP BY ub.KatAna', @IlgiliMetrik=NULL, @IlgiliKopru=N'products-code-stkid, salesproducts-products', @SonucNotu=N'compat 110: TRY_CONVERT yok → ISNUMERIC guard. Oyuncak ciro 700K→10,96M bu köprüyle düzeldi.', @Guven=0.95, @Kanit=N'pusula/sema/queries.yaml; calistirilarak dogrulandi', @TtlGun=180;
EXEC sem.sp_Query_Upsert @QueryId=N'eticaret-marka-satis', @Soru=N'E-ticaret marka/yayınevi bazında satış (dönem)', @DogrulanmisSql=N'SELECT it.BRAND, SUM(d.QUANTITY) adet,
       CAST(SUM(d.QUANTITY*d.SELLINGPRICE) AS decimal(18,0)) net
FROM ODAKJOKER.JOKER.dbo.J_ORDER_DETAILS d
JOIN ODAKJOKER.JOKER.dbo.J_ITEMS it ON it.LOGICALREF=d.ITEMREF
WHERE d.ORDERDATE >= ''20260601'' AND d.ORDERDATE < ''20260608''
GROUP BY it.BRAND', @IlgiliMetrik=NULL, @IlgiliKopru=N'orderdetails-orders, orderdetails-items', @SonucNotu=N'Linked server tarih = YYYYMMDD ISO (DMY sessiz hata!).', @Guven=0.95, @Kanit=N'pusula/sema/queries.yaml; calistirilarak dogrulandi', @TtlGun=180;
EXEC sem.sp_Query_Upsert @QueryId=N'cod-teslim-performans', @Soru=N'Kapıda ödeme teslim/iade performansı (olgun pencere)', @DogrulanmisSql=N'SELECT cs.STATUS durum, COUNT(*) siparis, CAST(SUM(o.TOTALPRICE) AS decimal(18,0)) tutar
FROM ODAKJOKER.JOKER.dbo.J_ORDERS o
JOIN ODAKJOKER.JOKER.dbo.J_ORDER_CARGO_STATUS cs ON cs.STATUS=o.CARGODELIVERYSTATUS
WHERE o.PAYDEFREF=-3
  AND o.ORDERDATE >= ''20260210'' AND o.ORDERDATE < ''20260526''
GROUP BY cs.STATUS', @IlgiliMetrik=N'cod_ekonomi', @IlgiliKopru=NULL, @SonucNotu=N'Olgun pencere: son 15 gün hariç (kargo süreci bitmemiş olur).', @Guven=0.95, @Kanit=N'pusula/sema/queries.yaml; calistirilarak dogrulandi', @TtlGun=180;
EXEC sem.sp_Query_Upsert @QueryId=N'depo-hareket-kategori', @Soru=N'Merkez depo hareket kategorileri (Mal Kabul/Heykel/İade/Sevk) yıl bazında', @DogrulanmisSql=N'SELECT YEAR(p.pikTarih) Yil,
  CASE WHEN p.pGC=0 AND i.eFirma=56 THEN ''Heykel''
       WHEN p.pGC=0 AND i.eTip=0  THEN ''MalKabul''
       WHEN p.pGC=0 AND i.eTip=9  THEN ''IadeKabul''
       WHEN p.pGC=0 AND i.eTip=16 THEN ''GenelGiris''
       WHEN p.pGC=1 AND i.eTip=13 THEN ''MagazaSevk''
       WHEN p.pGC=1 AND i.eTip IN (90,99) THEN ''IadeSevk''
       ELSE ''Diger'' END Kat,
  CAST(SUM(ABS(p.piAdet)) AS bigint) Adet
FROM DerinSISBkm.depo.paletIcHrk p WITH(NOLOCK)
JOIN DerinSISBkm.dbo.irs i WITH(NOLOCK) ON i.eID=p.piIrsID
WHERE MONTH(p.pikTarih) BETWEEN 1 AND 5 AND YEAR(p.pikTarih) IN (2024,2025,2026)
GROUP BY YEAR(p.pikTarih),
  CASE WHEN p.pGC=0 AND i.eFirma=56 THEN ''Heykel''
       WHEN p.pGC=0 AND i.eTip=0  THEN ''MalKabul''
       WHEN p.pGC=0 AND i.eTip=9  THEN ''IadeKabul''
       WHEN p.pGC=0 AND i.eTip=16 THEN ''GenelGiris''
       WHEN p.pGC=1 AND i.eTip=13 THEN ''MagazaSevk''
       WHEN p.pGC=1 AND i.eTip IN (90,99) THEN ''IadeSevk''
       ELSE ''Diger'' END', @IlgiliMetrik=N'depo_hareket_kategori', @IlgiliKopru=N'palet-irs, irs-firma', @SonucNotu=NULL, @Guven=0.95, @Kanit=N'pusula/sema/queries.yaml; calistirilarak dogrulandi', @TtlGun=180;
EXEC sem.sp_Query_Upsert @QueryId=N'depo-toplama-verim', @Soru=N'Depo toplama (picking) işgücü verimi — gerçek operatör', @DogrulanmisSql=N'SELECT YEAR(emTarih) Yil, COUNT(DISTINCT emKisi) Personel,
       COUNT(*) Islem, CAST(SUM(emAdet) AS bigint) Adet
FROM DerinSISBkm.depo.emirAyr WITH(NOLOCK)
WHERE emTamam=1 AND MONTH(emTarih) BETWEEN 1 AND 5
  AND YEAR(emTarih) IN (2024,2025,2026)
GROUP BY YEAR(emTarih)', @IlgiliMetrik=N'depo_isgucu', @IlgiliKopru=NULL, @SonucNotu=NULL, @Guven=0.95, @Kanit=N'pusula/sema/queries.yaml; calistirilarak dogrulandi', @TtlGun=180;
EXEC sem.sp_Query_Upsert @QueryId=N'musteri-adi-yazarkasa', @Soru=N'Yazarkasa fişindeki müşteri adı/telefonu', @DogrulanmisSql=N'SELECT TOP 100 s.Id, ISNULL(c.Name, s.CustomerCardNo) musteri, c.PhoneNumber
FROM EncoreMerkez.dbo.Sales s WITH(NOLOCK)
LEFT JOIN DerinCrm.dbo.Customer c ON c.Id=s.CustomersId
WHERE s.SaleDate >= CONVERT(date,''01.06.2026'',104)', @IlgiliMetrik=NULL, @IlgiliKopru=N'sales-customer-name', @SonucNotu=N'Group1Id=2 = personel müşteri. İç kartlar (Mağaza/Kumbara/599-699 tel) RFM''de filtrele.', @Guven=0.95, @Kanit=N'pusula/sema/queries.yaml; calistirilarak dogrulandi', @TtlGun=180;
EXEC sem.sp_Query_Upsert @QueryId=N'eticaret-haftalik-net-kanal', @Soru=N'E-ticaret haftalık net ciro, kanal kırılımı (iptal/iade hariç)', @DogrulanmisSql=N'SELECT CASE WHEN o.APPLICATION IN (''Mobil Uygulama (Android)'',''Mobil Uygulama (iOS)'',
            ''Mobil Site'',''Web Sitesi'') THEN o.APPLICATION ELSE ''Diğer'' END Kanal,
       SUM(CASE WHEN o.STATUS NOT IN (1001,1006,1007,3000,4000) THEN 1 ELSE 0 END) NetSiparis,
       SUM(CASE WHEN o.STATUS NOT IN (1001,1006,1007,3000,4000) THEN o.TOTALPRICE ELSE 0 END) NetCiro
FROM ODAKJOKER.JOKER.dbo.J_ORDERS o
WHERE o.ORDERDATE >= ''20260601'' AND o.ORDERDATE < ''20260608''
GROUP BY CASE WHEN o.APPLICATION IN (''Mobil Uygulama (Android)'',''Mobil Uygulama (iOS)'',
              ''Mobil Site'',''Web Sitesi'') THEN o.APPLICATION ELSE ''Diğer'' END', @IlgiliMetrik=NULL, @IlgiliKopru=NULL, @SonucNotu=N'Tarih ISO YYYYMMDD zorunlu. Net = STATUS 1006 (iptal) + 3004/3006 (iade) hariç. TOTALPRICE kargo dahil brüt sipariş — POS net''iyle birebir kıyaslanamaz.', @Guven=0.95, @Kanit=N'pusula/sema/queries.yaml; calistirilarak dogrulandi', @TtlGun=180;
EXEC sem.sp_Query_Upsert @QueryId=N'il-teslimat-perf', @Soru=N'İl bazında kargo teslimat performansı — çıkış (takvim + iş günü) + teslim süresi', @DogrulanmisSql=N'SELECT TOP 15 mus.DCITY AS Sehir, COUNT(*) AS Adet,
       CAST(AVG(CAST(DATEDIFF(HOUR,o.ORDERDATE,o.SENDDATE) AS float)/24) AS decimal(10,1)) AS CikisTakvim,
       CAST(AVG(CAST(
         DATEDIFF(DAY,o.ORDERDATE,o.SENDDATE) - DATEDIFF(WEEK,o.ORDERDATE,o.SENDDATE)*2
         - CASE WHEN DATEPART(WEEKDAY,o.ORDERDATE)=1 THEN 1 ELSE 0 END
         - CASE WHEN DATEPART(WEEKDAY,o.SENDDATE)=7 THEN 1 ELSE 0 END - ta.T AS float)) AS decimal(10,1)) AS CikisIsGunu,
       CAST(AVG(CAST(DATEDIFF(HOUR,o.SENDDATE,o.CARGODELIVERYDATE) AS float)/24) AS decimal(10,1)) AS TeslimGun
FROM ODAKJOKER.JOKER.dbo.J_ORDERS o
JOIN ODAKJOKER.JOKER.dbo.J_ORDER_DELIVERY_ADDRESS mus ON mus.LOGICALREF=o.DELIVERYREF
CROSS APPLY (SELECT COUNT(*) T FROM (VALUES (CONVERT(date,''20260423'')),(CONVERT(date,''20260501'')),
  (CONVERT(date,''20260519'')),(CONVERT(date,''20260527'')),(CONVERT(date,''20260528'')),
  (CONVERT(date,''20260529'')),(CONVERT(date,''20260530''))) H(d)
  WHERE H.d>o.ORDERDATE AND H.d<=o.SENDDATE AND DATEPART(WEEKDAY,H.d) NOT IN (1,7)) ta
WHERE o.SENDDATE>=''20260601'' AND o.SENDDATE<''20260613''
  AND o.CARGODELIVERYDATE IS NOT NULL AND o.STATUS=1005 AND mus.DCITY IS NOT NULL
GROUP BY mus.DCITY ORDER BY Adet DESC', @IlgiliMetrik=N'il_teslimat_perf', @IlgiliKopru=NULL, @SonucNotu=N'ÇIKIŞ iş günü olmalı (takvim 2x abartı). Depo Pzt-Cuma (Cmt 5/Paz 0). CROSS APPLY tatil tablosu hafta-içi resmi tatil çıkarır. Teslim takvim (kargo hafta sonu çalışır). Tatil sabiti yıllık güncelle.', @Guven=0.95, @Kanit=N'pusula/sema/queries.yaml; calistirilarak dogrulandi', @TtlGun=180;
EXEC sem.sp_Query_Upsert @QueryId=N'ay-cikis-trend', @Soru=N'Aylık kargoya çıkış süresi trendi (takvim + iş günü) — kapasite darboğazı', @DogrulanmisSql=N'SELECT YEAR(o.SENDDATE)*100+MONTH(o.SENDDATE) AS AyKod,
       COUNT(DISTINCT o.ORDERID) AS Siparis,
       CAST(AVG(CAST(DATEDIFF(HOUR,o.ORDERDATE,o.SENDDATE) AS float)/24) AS decimal(10,1)) AS CikisTakvim,
       CAST(AVG(CAST(
         DATEDIFF(DAY,o.ORDERDATE,o.SENDDATE) - DATEDIFF(WEEK,o.ORDERDATE,o.SENDDATE)*2
         - CASE WHEN DATEPART(WEEKDAY,o.ORDERDATE)=1 THEN 1 ELSE 0 END
         - CASE WHEN DATEPART(WEEKDAY,o.SENDDATE)=7 THEN 1 ELSE 0 END - ta.T AS float)) AS decimal(10,1)) AS CikisIsGunu
FROM ODAKJOKER.JOKER.dbo.J_ORDERS o
CROSS APPLY (SELECT COUNT(*) T FROM (VALUES (CONVERT(date,''20251029'')),(CONVERT(date,''20260101''))) H(d)
  WHERE H.d>o.ORDERDATE AND H.d<=o.SENDDATE AND DATEPART(WEEKDAY,H.d) NOT IN (1,7)) ta
WHERE o.SENDDATE>=''20250601'' AND o.SENDDATE<''20260601'' AND o.SENDDATE IS NOT NULL
  AND o.STATUS NOT IN (1001,1006,1007,3000,4000) AND DATEDIFF(DAY,o.ORDERDATE,o.SENDDATE)>=0
GROUP BY YEAR(o.SENDDATE)*100+MONTH(o.SENDDATE)', @IlgiliMetrik=N'il_teslimat_perf', @IlgiliKopru=NULL, @SonucNotu=N'Son 13 tam ay, dönem-bağımsız. CROSS APPLY tatil çıkarır (örnekte kısmi liste). Grafik iş günü serisi.', @Guven=0.95, @Kanit=N'pusula/sema/queries.yaml; calistirilarak dogrulandi', @TtlGun=180;
EXEC sem.sp_Query_Upsert @QueryId=N'cod-iade-maliyet-ozet', @Soru=N'Kapıda ödeme (COD) iade maliyeti özeti — sipariş/teslim/iade oranı + 2×kargo iade gideri', @DogrulanmisSql=N'SELECT COUNT(*) AS Siparis,
       SUM(CASE WHEN o.STATUS=1005 THEN 1 ELSE 0 END) AS Teslim,
       SUM(CASE WHEN o.CARGODELIVERYSTATUS=2 THEN 1 ELSE 0 END) AS Iade,
       CAST(SUM(o.SERVICEPRICE) AS decimal(18,0)) AS KapidaBedel,
       CAST(SUM(CASE WHEN o.CARGODELIVERYSTATUS=2 THEN 2*o.CARGOPRICE ELSE 0 END) AS decimal(18,0)) AS IadeMaliyet
FROM ODAKJOKER.JOKER.dbo.J_ORDERS o
WHERE o.PAYDEFREF=-3 AND o.SENDDATE>=''20260501'' AND o.SENDDATE<''20260601'' AND o.SENDDATE IS NOT NULL', @IlgiliMetrik=N'cod_ekonomi', @IlgiliKopru=NULL, @SonucNotu=N'İade maliyeti = 2×CARGOPRICE (gidiş+geri getirme, teslim edilmeyen COD). SERVICEPRICE pass-through (firmaya, kâr değil). CARGODELIVERYSTATUS=2=iade. Çıkış (SENDDATE) dönemi — kısmi son ay iade oranını düşük gösterir (iade gecikmeli gelir).', @Guven=0.95, @Kanit=N'pusula/sema/queries.yaml; calistirilarak dogrulandi', @TtlGun=180;
GO

